bool envelope(const Json &e,const char *domain,const Json &keys,size_t limit,Json &payload,std::string &raw){if(!e.keys("schema,key_id,payload_b64,signature_b64")||e.num("schema")!=1||!identifier(e.text("key_id"))||keys.get(e.text("key_id")).type!=Json::String)return false;std::string signature;if(!unbase64(e.text("payload_b64"),raw,limit)||!unbase64(e.text("signature_b64"),signature,128)||!verifySignature(keys.get(e.text("key_id")).string,std::string(domain)+raw,signature)||!parse(raw,payload,limit)||payload.type!=Json::Object)return false;return true;}
static bool safePath(const std::string &s){if(s.empty()||s[0]!='/'||s.size()>511||s[s.size()-1]=='/')return false;size_t p=1;while(p<s.size()){size_t q=s.find('/',p);if(!identifier(s.substr(p,q==std::string::npos?q:q-p)))return false;if(q==std::string::npos)return true;p=q+1;}return false;}
static Json fileIdentity(const Json &f){Json j=f;j.object.erase("source");return j;}
bool validateFiles(const Json &a,const std::string &native,const std::string &boot,bool source){if(a.type!=Json::Array||a.array.size()<3||a.array.size()>128||!hex(native)||!hex(boot,24))return false;unsigned entries=0,pointers=0;std::map<std::string,bool> paths;std::string system="/etc/pandanote-system/"+boot+"/",release="/user/pandanote/apps/releases/"+native+"/";for(size_t i=0;i<a.array.size();i++){const Json&f=a.array[i];if(!(source?f.keys("path,mode,bytes,sha256,role,source"):f.keys("path,mode,bytes,sha256,role"))||!safePath(f.text("path"))||!hex(f.text("sha256"))||f.num("bytes")<0||f.num("bytes")>24*1024*1024)return false;std::string path=f.text("path"),role=f.text("role");if(path==release+"manifest.json"&&f.text("sha256")!=native)return false;if((path==release+"reader-shell.mipsel"||path==release+"ota/ota-worker.mipsel"||path==release+"ota/pandanote-ota-upgrade.mipsel")&&f.num("mode")!=0700)return false;if(source&&f.text("source")!="files"+path)return false;if(role=="system"){if(path.find(system)!=0||f.num("mode")!=0600)return false;}else if(role=="release"){if(path.find(release)!=0||(f.num("mode")!=0600&&f.num("mode")!=0700))return false;}else if(role=="entry"){if(path!="/etc/inittab"||f.num("mode")!=0644||++entries!=1)return false;}else if(role=="pointer"){if(path!="/user/pandanote/apps/current"||f.num("mode")!=0600||++pointers!=1)return false;}else return false;for(std::map<std::string,bool>::const_iterator j=paths.begin();j!=paths.end();++j){if(path==j->first||path.find(j->first+"/")==0||j->first.find(path+"/")==0)return false;}paths[path]=true;}return entries==1&&pointers==1&&paths.count(release+"reader-shell.mipsel")&&paths.count(release+"manifest.json")&&paths.count(release+"release.sha256")&&paths.count(release+"ota/ota-worker.mipsel")&&paths.count(release+"ota/pandanote-ota-upgrade.mipsel")&&paths.count(release+"ota/helper-manifest.json")&&paths.count(system+"service.sh")&&paths.count(system+"SHA256SUMS");}
static bool equalFiles(const Json &a,const Json &b){if(a.type!=Json::Array||b.type!=Json::Array||a.array.size()!=b.array.size())return false;std::map<std::string,std::string> m;for(size_t i=0;i<a.array.size();i++)m[a.array[i].text("path")]=encode(fileIdentity(a.array[i]));for(size_t i=0;i<b.array.size();i++)if(m[b.array[i].text("path")]!=encode(fileIdentity(b.array[i])))return false;return true;}
bool authorize(const Json &response,const Json &config,const Json &request,int64_t now,Authorization &a,std::string &error){error="signature_invalid";if(!response.keys("schema,status,release,deployment,candidate_b64")||response.num("schema")!=1||response.text("status")!="update"||!envelope(response.get("release"),"PANDANOTE-OTA-RELEASE-1\n",config.get("keys"),256*1024,a.release,a.releaseRaw))return false;std::string raw;if(!envelope(response.get("deployment"),"PANDANOTE-OTA-DEPLOYMENT-1\n",config.get("keys"),16384,a.deployment,raw))return false;const Json &r=a.release,&d=a.deployment;if(!r.keys("schema,model,channel,sequence,version,native_sha256,boot_id,ota_abi,workspace_schema,files")||!d.keys("schema,device_id,request_nonce,release_sha256,sequence,old_package_sha256,old_native_sha256,old_boot_id,old_inittab_sha256,old_current_sha256,live_superblock_sha256,candidate_sha256,bundle_sha256,bundle_bytes,helper_sha256,issued_at,expires_at")||r.num("schema")!=1||d.num("schema")!=1||r.num("ota_abi")!=1||r.num("workspace_schema")!=1||r.text("model")!=config.text("model")||r.text("channel")!=config.text("channel")||r.text("version").empty()||r.text("version").size()>128||!validateFiles(r.get("files"),r.text("native_sha256"),r.text("boot_id"),false))return false;
 error="authorization_expired";if(now<946684800LL||d.num("issued_at")<946684800LL||d.num("issued_at")>now||d.num("expires_at")<=now||d.num("expires_at")-d.num("issued_at")>86400||d.num("expires_at")<=d.num("issued_at"))return false;
 error="baseline_mismatch";if(d.text("device_id")!=config.text("device_id")||d.text("request_nonce")!=request.text("request_nonce")||!hex(d.text("request_nonce"))||r.num("sequence")<request.num("highest_sequence")||(r.num("sequence")==request.num("highest_sequence")&&config.text("accepted_release_sha256")!=digest(a.releaseRaw))||r.num("sequence")<=0||d.num("sequence")!=r.num("sequence")||d.text("release_sha256")!=digest(a.releaseRaw)||!hex(d.text("bundle_sha256"))||!hex(d.text("helper_sha256"))||d.text("helper_sha256")!=config.text("helper_sha256")||d.num("bundle_bytes")<100||d.num("bundle_bytes")>24*1024*1024)return false;
 const char*fields[]={"old_package_sha256","old_native_sha256","old_boot_id","old_inittab_sha256","old_current_sha256","live_superblock_sha256"};for(unsigned i=0;i<6;i++)if(d.text(fields[i])!=request.text(fields[i])||!hex(d.text(fields[i]),i==2?24:64))return false;
 error="bundle_invalid";if(!unbase64(response.text("candidate_b64"),a.candidateRaw,256*1024)||digest(a.candidateRaw)!=d.text("candidate_sha256")||!parse(a.candidateRaw,a.candidate,256*1024))return false;const Json &c=a.candidate,&old=c.get("upgrade_from");if(c.num("schema")!=1||c.text("profile")!="normal-persistent-v1"||c.text("native_sha256")!=r.text("native_sha256")||c.text("boot_id")!=r.text("boot_id")||c.text("old_inittab_sha256")!=d.text("old_inittab_sha256")||!validateFiles(c.get("files"),r.text("native_sha256"),r.text("boot_id"),true)||!equalFiles(c.get("files"),r.get("files"))||r.text("native_sha256")==d.text("old_native_sha256")||r.text("boot_id")==d.text("old_boot_id"))return false;for(unsigned i=0;i<6;i++)if(old.text(fields[i])!=d.text(fields[i]))return false;if(!old.keys("schema,profile,old_package_sha256,old_native_sha256,old_boot_id,old_inittab_sha256,old_current_sha256,live_superblock_sha256,old_files")||old.num("schema")!=1||old.text("profile")!="normal-exact-upgrade-v1")return false;if(old.get("old_files").type!=Json::Array||old.get("old_files").array.size()<4||old.get("old_files").array.size()>128)return false;error="none";return true;}
static bool line(int fd,std::string &s){s.clear();char c;while(s.size()<1024){ssize_t n=read(fd,&c,1);if(n!=1)return false;if(c=='\n')return true;if(!c)return false;s+=c;}return false;}
bool validateBundle(const std::string &path,const Authorization &a){std::string h;uint64_t bytes;if(!hashFile(path,h,&bytes)||h!=a.deployment.text("bundle_sha256")||bytes!=uint64_t(a.deployment.num("bundle_bytes")))return false;int fd=openFile(path,O_RDONLY);if(fd<0)return false;bool ok=true;std::string l,magic,boot,native,entry,extra,package,current,sb;unsigned n=0,oldn=0;const Json&r=a.release,&d=a.deployment;do{if(!line(fd,l)){ok=false;break;}std::istringstream first(l);if(!(first>>magic>>boot>>native>>entry>>n)||(first>>extra)||magic!="PANDANOTE-UPGRADE-1"||boot!=r.text("boot_id")||native!=r.text("native_sha256")||entry!=d.text("old_inittab_sha256")||n!=r.get("files").array.size()){ok=false;break;}if(!line(fd,l)){ok=false;break;}std::istringstream base(l);if(!(base>>magic>>package>>native>>boot>>current>>sb>>oldn)||(base>>extra)||magic!="BASE"||package!=d.text("old_package_sha256")||native!=d.text("old_native_sha256")||boot!=d.text("old_boot_id")||current!=d.text("old_current_sha256")||sb!=d.text("live_superblock_sha256")||oldn!=a.candidate.get("upgrade_from").get("old_files").array.size()){ok=false;break;}
 for(unsigned i=0;i<oldn&&ok;i++){if(!line(fd,l)){ok=false;break;}std::string sha,path;unsigned mode;uint64_t size;std::istringstream check(l);const Json &f=a.candidate.get("upgrade_from").get("old_files").array[i];if(!(check>>magic>>std::oct>>mode>>std::dec>>size>>sha>>path)||(check>>extra)||magic!="CHECK"||mode!=unsigned(f.num("mode"))||size!=uint64_t(f.num("bytes"))||sha!=f.text("sha256")||path!=f.text("path"))ok=false;}
 std::map<std::string,bool> seen;for(unsigned i=0;i<n&&ok;i++){if(!line(fd,l)){ok=false;break;}std::string role,sha,path;unsigned mode;uint64_t size;std::istringstream row(l);if(!(row>>role>>std::oct>>mode>>std::dec>>size>>sha>>path)||(row>>extra)||size>24*1024*1024||seen.count(path)){ok=false;break;}seen[path]=true;bool found=false;for(size_t j=0;j<r.get("files").array.size();j++){const Json&f=r.get("files").array[j];if(f.text("path")==path)found=mode==unsigned(f.num("mode"))&&size==uint64_t(f.num("bytes"))&&sha==f.text("sha256")&&role==f.text("role");}if(!found){ok=false;break;}SHA256_CTX c;sha256_init(&c);unsigned char b[16384],out[32];uint64_t remain=size;while(remain){ssize_t z=read(fd,b,remain>sizeof b?sizeof b:size_t(remain));if(z<=0){ok=false;break;}sha256_update(&c,b,z);remain-=z;}sha256_final(&c,out);char digestText[65];for(unsigned j=0;j<32;j++)snprintf(digestText+2*j,3,"%02x",out[j]);char end;if(!ok||sha!=digestText||read(fd,&end,1)!=1||end!='\n'){ok=false;break;}}
 char end;if(ok&&read(fd,&end,1)!=0)ok=false;
 }while(false);close(fd);return ok;}
